pagoda.source:
const n = params.tiers;
const totalH = 12;
const baseH = 0.65;
const finialH = 1.45;
const storyH = (totalH - baseH - finialH) / n;
const roofH = storyH * 0.37;
const wallH = storyH * 0.60;
const stone = { preset: 'stone', color: '#77756f', roughness: 0.92, flatShading: true };
const stoneDark = { preset: 'stone', color: '#555650', roughness: 0.95 };
const wall = { preset: 'concrete', color: params.wallColor, roughness: 0.8 };
const timber = { preset: 'wood', color: '#6d241b', roughness: 0.72 };
const darkWood = { preset: 'wood', color: '#351b17', roughness: 0.78 };
const roof = { preset: 'brick', color: params.roofColor, roughness: 0.58, flatShading: true };
const roofEdge = { preset: 'metal', color: api.mix(params.roofColor, '#17241f', 0.38), metalness: 0.22, roughness: 0.5 };
const gold = { preset: 'gold', color: '#d6a62d', metalness: 0.72, roughness: 0.28 };
api.add(api.box(5.7, 0.28, 5.7).translate(0, 0.14, 0), stoneDark);
api.add(api.box(5.2, 0.37, 5.2).translate(0, 0.465, 0), stone);
for (let k = 0; k < 4; k++) {
  const a = k * Math.PI * 0.5;
  const x = Math.cos(a) * 2.72;
  const z = Math.sin(a) * 2.72;
  api.add(api.sphere(0.16, 1).scale(1, 0.55, 1).translate(x, 0.36, z), stoneDark);
}
let y = baseH;
let topWidth = 0;
for (let i = 0; i < n; i++) {
  const t = i / Math.max(1, n - 1);
  const wallW = 3.85 - t * 1.55;
  const deckW = wallW + 0.72;
  const roofW = wallW + 1.55;
  const wallY = y + wallH * 0.5;
  api.add(api.box(deckW, storyH * 0.09, deckW).translate(0, y + storyH * 0.045, 0), darkWood);
  api.add(api.box(wallW, wallH, wallW).translate(0, wallY, 0), wall);
  const post = Math.max(0.09, wallW * 0.035);
  for (let sx = -1; sx <= 1; sx += 2) {
    for (let sz = -1; sz <= 1; sz += 2) {
      api.add(api.box(post, wallH * 1.06, post).translate(sx * wallW * 0.48, wallY, sz * wallW * 0.48), timber);
    }
  }
  const beamY = y + wallH * 0.83;
  for (let q = 0; q < 4; q++) {
    api.add(api.box(wallW + post, post * 1.25, post * 0.9).translate(0, beamY, wallW * 0.505).rotate(0, q * 90, 0), timber);
    const faceZ = wallW * 0.507;
    for (let j = -2; j <= 2; j++) {
      const px = j * wallW * 0.145;
      api.add(api.box(post * 0.52, wallH * 0.48, post * 0.45).translate(px, y + wallH * 0.42, faceZ).rotate(0, q * 90, 0), darkWood);
    }
    api.add(api.box(wallW * 0.76, post * 0.48, post * 0.42).translate(0, y + wallH * 0.42, faceZ * 1.004).rotate(0, q * 90, 0), darkWood);
  }
  const railY = y + storyH * 0.25;
  if (i < n - 1) {
    for (let q = 0; q < 4; q++) {
      const rz = deckW * 0.46;
      api.add(api.box(deckW * 0.88, post * 0.38, post * 0.38).translate(0, railY, rz).rotate(0, q * 90, 0), darkWood);
      for (let j = -3; j <= 3; j++) {
        api.add(api.box(post * 0.3, storyH * 0.22, post * 0.3).translate(j * deckW * 0.115, y + storyH * 0.15, rz).rotate(0, q * 90, 0), darkWood);
      }
    }
  }
  const roofBaseY = y + wallH;
  const roofCenterY = roofBaseY + roofH * 0.42;
  api.add(api.cone(roofW * 0.71, roofH * 0.78, 4).rotate(0, 45, 0).translate(0, roofBaseY + roofH * 0.39, 0), roof);
  api.add(api.box(roofW, storyH * 0.055, roofW).translate(0, roofBaseY + storyH * 0.028, 0), roofEdge);
  const rise = roofH * 0.25;
  const thick = Math.max(0.08, storyH * 0.055);
  const fascia = [[-roofW * 0.5, 0], [roofW * 0.5, 0], [roofW * 0.57, rise], [roofW * 0.51, rise + thick], [-roofW * 0.51, rise + thick], [-roofW * 0.57, rise]];
  for (let q = 0; q < 4; q++) {
    api.add(api.extrude(fascia, thick).translate(0, roofBaseY, roofW * 0.47).rotate(0, q * 90, 0), roofEdge);
  }
  for (let q = 0; q < 4; q++) {
    const a = q * Math.PI * 0.5 + Math.PI * 0.25;
    api.add(api.sphere(thick * 0.72, 1).translate(Math.cos(a) * roofW * 0.74, roofBaseY + rise * 1.02, Math.sin(a) * roofW * 0.74), gold);
  }
  api.collider({ kind: 'box', halfExtents: [deckW * 0.5, storyH * 0.045, deckW * 0.5], offset: [0, y + storyH * 0.045, 0] });
  api.collider({ kind: 'box', halfExtents: [wallW * 0.5, wallH * 0.5, wallW * 0.5], offset: [0, wallY, 0] });
  y += storyH;
  topWidth = roofW;
}
const spireBase = totalH - finialH;
api.add(api.cylinder(topWidth * 0.15, topWidth * 0.19, finialH * 0.13, 12).translate(0, spireBase + finialH * 0.065, 0), gold);
api.add(api.sphere(finialH * 0.13, 2).scale(1, 0.7, 1).translate(0, spireBase + finialH * 0.22, 0), gold);
const mast = api.cylinder(finialH * 0.035, finialH * 0.055, finialH * 0.72, 10).translate(0, spireBase + finialH * 0.55, 0);
api.add(mast, gold);
for (let j = 0; j < 4; j++) {
  const rr = finialH * (0.19 - j * 0.025);
  api.add(api.torus(rr, finialH * 0.025).rotate(90, 0, 0).translate(0, spireBase + finialH * (0.38 + j * 0.12), 0), gold);
}
api.add(api.cone(finialH * 0.09, finialH * 0.28, 10).translate(0, totalH - finialH * 0.14, 0), gold);
api.collider({ kind: 'box', halfExtents: [2.85, 0.14, 2.85], offset: [0, 0.14, 0] });
api.collider({ kind: 'cylinder', radius: finialH * 0.06, halfHeight: finialH * 0.45, offset: [0, spireBase + finialH * 0.52, 0] });
return api.build();

torii-gate.source:
const h = params.height;
const span = h * 0.72;
const postR = h * 0.055;
const baseH = h * 0.105;
const postTop = h * 0.86;
const beamDepth = h * 0.105;
const vermilion = { preset: 'wood', color: params.color, roughness: 0.62 };
const dark = { preset: 'stone', color: '#17191c', roughness: 0.82 };
const blackWood = { preset: 'wood', color: '#24201d', roughness: 0.68 };
const gold = { preset: 'gold', color: '#d5ad4d', metalness: 0.65, roughness: 0.35 };
for (let side = -1; side <= 1; side += 2) {
  const x = side * span * 0.36;
  api.add(api.cylinder(postR * 1.32, postR * 1.48, baseH, 16).translate(x, baseH * 0.5, 0), dark);
  api.add(api.cylinder(postR * 1.12, postR * 1.28, h * 0.045, 16).translate(x, baseH + h * 0.0225, 0), blackWood);
  api.add(api.cylinder(postR * 0.82, postR, postTop - baseH, 16).translate(x, baseH + (postTop - baseH) * 0.5, 0), vermilion);
  api.add(api.cylinder(postR * 1.16, postR * 1.16, h * 0.035, 16).translate(x, h * 0.73, 0), vermilion);
  api.add(api.cylinder(postR * 1.28, postR * 1.05, h * 0.045, 16).translate(x, postTop - h * 0.012, 0), vermilion);
}
const lowerY = h * 0.72;
api.add(api.box(span * 0.82, h * 0.075, beamDepth * 0.8).translate(0, lowerY, 0), vermilion);
api.add(api.box(span * 0.91, h * 0.027, beamDepth * 0.94).translate(0, lowerY + h * 0.049, 0), blackWood);
const halfW = span * 0.58;
const beamShape = [
  [-halfW, h * 0.055],
  [-span * 0.49, h * 0.043],
  [-span * 0.28, h * 0.019],
  [0, h * 0.012],
  [span * 0.28, h * 0.019],
  [span * 0.49, h * 0.043],
  [halfW, h * 0.055],
  [halfW * 0.985, -h * 0.026],
  [span * 0.48, -h * 0.034],
  [span * 0.27, -h * 0.049],
  [0, -h * 0.052],
  [-span * 0.27, -h * 0.049],
  [-span * 0.48, -h * 0.034],
  [-halfW * 0.985, -h * 0.026]
];
api.add(api.extrude(beamShape, beamDepth).translate(0, h * 0.895, 0), vermilion);
const capShape = [
  [-halfW * 1.025, h * 0.018],
  [-span * 0.5, h * 0.012],
  [-span * 0.28, h * 0.004],
  [0, 0],
  [span * 0.28, h * 0.004],
  [span * 0.5, h * 0.012],
  [halfW * 1.025, h * 0.018],
  [halfW, -h * 0.006],
  [0, -h * 0.02],
  [-halfW, -h * 0.006]
];
api.add(api.extrude(capShape, beamDepth * 1.1).translate(0, h * 0.967, 0), blackWood);
const plaqueW = span * 0.18;
const plaqueH = h * 0.105;
api.add(api.box(plaqueW, plaqueH, beamDepth * 1.02).translate(0, h * 0.797, 0), blackWood);
api.add(api.box(plaqueW * 0.72, plaqueH * 0.12, beamDepth * 1.045).translate(0, h * 0.817, 0), gold);
api.add(api.box(plaqueW * 0.42, plaqueH * 0.1, beamDepth * 1.05).translate(0, h * 0.785, 0), gold);
for (let side = -1; side <= 1; side += 2) {
  api.collider({ kind: 'cylinder', radius: postR * 1.3, halfHeight: postTop * 0.5, offset: [side * span * 0.36, postTop * 0.5, 0] });
}
api.collider({ kind: 'box', halfExtents: [span * 0.46, h * 0.055, beamDepth * 0.5], offset: [0, lowerY, 0] });
api.collider({ kind: 'box', halfExtents: [halfW, h * 0.065, beamDepth * 0.56], offset: [0, h * 0.925, 0] });
return api.build();

waterfall.source:
const h = params.height;
const u = h / 5;
const waterColor = params.waterColor;
const rockMat = { preset: 'stone', roughness: 0.95, flatShading: true, vertexColors: true };
const darkRock = '#4d5552';
const midRock = '#68716c';
const lightRock = '#858c82';
const moss = '#52674a';
const waterMat = { preset: 'water', color: waterColor, opacity: 0.7, roughness: 0.08, emissive: waterColor, emissiveIntensity: 0.16 };
const foamMat = { preset: 'water', color: '#dff7f5', opacity: 0.82, roughness: 0.2, emissive: '#bfe8e8', emissiveIntensity: 0.3 };
const stoneMat = { preset: 'stone', roughness: 0.95, flatShading: true, vertexColors: true };
function rockColor(x, y, z) {
  const n = api.noise3(x * 1.8 / u, y * 1.6 / u, z * 1.8 / u);
  const base = n > 0.28 ? lightRock : (n < -0.3 ? darkRock : midRock);
  return y > h * 0.12 && api.noise2(x * 2 / u, z * 2 / u) > 0.48 ? api.mix(base, moss, 0.45) : base;
}
const lower = api.box(u * 3.6, u * 1.55, u * 1.65).translate(0, u * 0.775, -u * 0.72);
lower.displace((x, y, z) => api.noise3(x * 2.2 / u, y * 2 / u, z * 2.2 / u) * u * 0.055).vertexColor(rockColor);
api.add(lower, rockMat);
const middle = api.box(u * 3.05, u * 1.55, u * 1.5).translate(0.08 * u, u * 2.275, -u * 0.93);
middle.displace((x, y, z) => api.noise3(x * 2.4 / u, y * 2 / u, z * 2.4 / u) * u * 0.06).vertexColor(rockColor);
api.add(middle, rockMat);
const upper = api.box(u * 2.55, u * 1.9, u * 1.35).translate(-0.1 * u, u * 4.05, -u * 1.08);
upper.displace((x, y, z) => api.noise3(x * 2.5 / u, y * 2 / u, z * 2.5 / u) * u * 0.065).vertexColor(rockColor);
api.add(upper, rockMat);
for (let i = 0; i < 9; i++) {
  const a = i * 2.399;
  const rx = Math.cos(a) * u * (1.45 + 0.35 * api.rng());
  const rz = -u * (0.8 + 0.5 * api.rng()) + Math.sin(a) * u * 0.55;
  const rr = u * (0.25 + api.rng() * 0.22);
  const ry = rr * (0.75 + api.rng() * 0.55);
  const r = api.icosphereRock(rr, 0.65).scale(1.2, ry / rr, 0.9).translate(rx, rr * 0.55, rz);
  r.vertexColor(rockColor);
  api.add(r, stoneMat);
}
const poolR = u * 2.15;
const basin = api.lathe([[0,0],[poolR,0],[poolR,u*0.18],[poolR*0.94,u*0.27],[poolR*0.82,u*0.18],[0,u*0.12]],28).translate(0,0,u*1.2);
basin.vertexColor((x,y,z) => api.mix(darkRock, lightRock, 0.38 + 0.22 * api.noise3(x/u,y/u,z/u)));
api.add(basin, stoneMat);
api.add(api.cylinder(poolR * 0.84, poolR * 0.84, u * 0.055, 28).translate(0, u * 0.205, u * 1.2), waterMat);
const falls = [
  [-0.08*u, u*4.91, -0.37*u, u*1.48, u*1.62],
  [0.06*u, u*3.32, -0.12*u, u*1.65, u*1.50],
  [-0.02*u, u*1.72, 0.28*u, u*1.82, u*1.48]
];
for (let i = 0; i < falls.length; i++) {
  const f = falls[i];
  const sheet = api.box(f[3], f[4], u * 0.055).translate(f[0], f[1] - f[4] * 0.5, f[2]);
  sheet.vertexColor((x,y,z) => api.mix(waterColor, '#d6f4f4', 0.18 + 0.28 * (0.5 + 0.5 * api.noise3(x*5/u,y*4/u,z*3/u))));
  api.add(sheet, waterMat);
  api.add(api.box(f[3] * 0.96, u * 0.075, u * 0.34).translate(f[0], f[1] - f[4] + u * 0.035, f[2] + u * 0.13), foamMat);
}
for (let i = 0; i < 7; i++) {
  const x = (i - 3) * u * 0.25;
  const stream = api.tube([[x,u*4.86,-u*0.32],[x + api.noise2(i,1)*u*0.05,u*3.7,-u*0.25],[x + api.noise2(i,2)*u*0.07,u*2.35,u*0.02],[x + api.noise2(i,3)*u*0.08,u*0.35,u*0.43]],u*0.025,5);
  api.add(stream, foamMat);
}
for (let i = 0; i < 12; i++) {
  const a = i * Math.PI * 2 / 12;
  const rad = u * (0.3 + api.rng() * 0.48);
  const bubble = api.icosphereRock(u * (0.065 + api.rng() * 0.055),0.25).scale(1.8,0.35,1).translate(Math.cos(a)*rad,u*0.25,u*0.62 + Math.sin(a)*rad*0.5);
  api.add(bubble, foamMat);
}
for (let i = 0; i < 3; i++) {
  api.add(api.torus(u * (0.42 + i * 0.27), u * 0.018).rotate(90,0,0).scale(1,1,0.55).translate(0,u*(0.245+i*0.006),u*0.95), foamMat);
}
for (let i = 0; i < 14; i++) {
  const a = i * Math.PI * 2 / 14 + 0.15;
  const rr = u * (0.18 + 0.08 * api.rng());
  const px = Math.cos(a) * poolR * 0.9;
  const pz = u * 1.2 + Math.sin(a) * poolR * 0.9;
  const rimRock = api.icosphereRock(rr,0.7).scale(1.35,0.7,1).translate(px,u*0.2,pz);
  rimRock.vertexColor(rockColor);
  api.add(rimRock,stoneMat);
}
api.collider({ kind: 'box', halfExtents: [u*1.8,u*0.78,u*0.83], offset: [0,u*0.78,-u*0.72] });
api.collider({ kind: 'box', halfExtents: [u*1.53,u*0.78,u*0.75], offset: [0.08*u,u*2.28,-u*0.93] });
api.collider({ kind: 'box', halfExtents: [u*1.28,u*0.95,u*0.68], offset: [-0.1*u,u*4.05,-u*1.08] });
api.collider({ kind: 'cylinder', radius: poolR, halfHeight: u*0.13, offset: [0,u*0.13,u*1.2] });
return api.build();
